const cfg = $('Settings').first().json;
const post = $input.first().json.posts[0];
const tags = post.tags.map(t => t.slug);
if (!tags.includes('hash-audio') && !['manual', 'backlog'].includes(cfg.event)) return [];
if (post.status !== 'published' && cfg.event !== 'manual') return [];
// Narration is uploaded to a public CDN and its card sits above any paywall, so only public posts are narrated
if (post.visibility !== 'public') return [];
const refresh = tags.includes('hash-audio-refresh');

// Read text from lexical so the inserted audio card never changes the fingerprint; code blocks and images are skipped on purpose
// The AI summary toggle ("resumen"/"summary", from Ghost: AI Summary Card) is skipped too, so adding it does not mark the audio stale
const isSummary = n => n.type === 'toggle' && ['resumen', 'summary'].includes(String(n.heading || '').replace(/<[^>]+>/g, '').trim());
const textOf = n => n.type === 'audio' || isSummary(n) ? '' : typeof n.text === 'string' ? n.text : (n.children || []).map(textOf).join(['root', 'list'].includes(n.type) ? '\n' : '');
const lexical = JSON.parse(post.lexical);
const rawText = (post.title + '.\n' + textOf(lexical.root)).replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
const sections = [];
let section;
let contentBlock = -1;
const addBlock = (value, block, type) => {
  const raw = String(value || '').replace(/[ \t]+/g, ' ').trim();
  if (!raw) return;
  if (type === 'heading' || type === 'extended-heading' || !section) {
    section = { anchor: block, text: '' };
    sections.push(section);
  }
  section.text += (section.text ? '\n' : '') + raw;
};
addBlock(post.title, -1, 'title');
for (const node of lexical.root.children) {
  if (node.type === 'audio') continue;
  contentBlock++;
  addBlock(textOf(node), contentBlock, node.type);
}

// From the site, not the post: a guess from the slug read Spanish posts without -es as English.
const lang = /^https:\/\/en\./.test(cfg.ghostUrl) ? 'en' : 'es';

function spanishInteger(value) {
  const n = Number(value);
  if (!Number.isSafeInteger(n) || n < 0 || n >= 1000000000) return String(value);
  if (n === 0) return 'cero';
  const units = ['', 'uno', 'dos', 'tres', 'cuatro', 'cinco', 'seis', 'siete', 'ocho', 'nueve'];
  const specials = ['diez', 'once', 'doce', 'trece', 'catorce', 'quince', 'dieciséis', 'diecisiete', 'dieciocho', 'diecinueve'];
  const twenties = ['veinte', 'veintiuno', 'veintidós', 'veintitrés', 'veinticuatro', 'veinticinco', 'veintiséis', 'veintisiete', 'veintiocho', 'veintinueve'];
  const tens = ['', '', '', 'treinta', 'cuarenta', 'cincuenta', 'sesenta', 'setenta', 'ochenta', 'noventa'];
  const hundreds = ['', 'ciento', 'doscientos', 'trescientos', 'cuatrocientos', 'quinientos', 'seiscientos', 'setecientos', 'ochocientos', 'novecientos'];
  const under100 = x => x < 10 ? units[x] : x < 20 ? specials[x - 10] : x < 30 ? twenties[x - 20] : tens[Math.floor(x / 10)] + (x % 10 ? ' y ' + units[x % 10] : '');
  const under1000 = x => x === 100 ? 'cien' : x < 100 ? under100(x) : hundreds[Math.floor(x / 100)] + (x % 100 ? ' ' + under100(x % 100) : '');
  if (n < 1000) return under1000(n);
  if (n < 1000000) {
    const thousands = Math.floor(n / 1000), rest = n % 1000;
    return (thousands === 1 ? 'mil' : under1000(thousands) + ' mil') + (rest ? ' ' + under1000(rest) : '');
  }
  const millions = Math.floor(n / 1000000), rest = n % 1000000;
  return (millions === 1 ? 'un millón' : under1000(millions) + ' millones') + (rest ? ' ' + spanishInteger(rest) : '');
}
function spanishNumber(raw) {
  const value = String(raw);
  if (/^\d{1,3}(?:\.\d{3})+$/.test(value)) return spanishInteger(value.replace(/\./g, ''));
  const decimal = value.match(/^(\d+),(\d+)$/);
  if (decimal) {
    const fraction = decimal[2];
    const leading = fraction.match(/^0+/)?.[0].length || 0;
    const fractionalWords = leading === fraction.length
      ? fraction.split('').map(() => 'cero').join(' ')
      : (leading ? 'cero '.repeat(leading) : '') + spanishInteger(Number(fraction));
    return spanishInteger(decimal[1]) + ' coma ' + fractionalWords;
  }
  return /^\d+$/.test(value) ? spanishInteger(value) : value;
}
function normalizeSpanishNumbers(input) {
  let text = String(input);
  const number = '\\d{1,3}(?:\\.\\d{3})+|\\d+(?:,\\d+)?';
  const range = new RegExp('(' + number + ')\\s*[-–—]\\s*(' + number + ')\\s*%', 'g');
  text = text.replace(range, (_, a, b) => spanishNumber(a) + ' a ' + spanishNumber(b) + ' por ciento');
  text = text.replace(new RegExp('(' + number + ')\\s*%', 'g'), (_, n) => spanishNumber(n) + ' por ciento');
  const currencies = {
    USD: ['dólar estadounidense', 'dólares estadounidenses'], EUR: ['euro', 'euros'], COP: ['peso colombiano', 'pesos colombianos'],
    MXN: ['peso mexicano', 'pesos mexicanos'], ARS: ['peso argentino', 'pesos argentinos']
  };
  const moneyNumber = '\\d{1,3}(?:\\.\\d{3})+|\\d+(?:[.,]\\d{1,2})?';
  const money = (code, raw) => {
    const names = currencies[code.toUpperCase()];
    const thousands = /^\d{1,3}(?:\.\d{3})+$/.test(raw);
    const parts = raw.split(/[.,]/);
    if (!thousands && parts.length === 2) {
      const whole = Number(parts[0]), fraction = Number(parts[1]);
      if (fraction === 0) return (whole === 1 ? 'un' : spanishInteger(whole)) + ' ' + (whole === 1 ? names[0] : names[1]);
      if (whole === 0) {
        const unit = code.toUpperCase() === 'USD' ? 'dólar' : names[0];
        return spanishInteger(fraction) + ' ' + (fraction === 1 ? 'centavo' : 'centavos') + ' de ' + unit;
      }
      const unit = code.toUpperCase() === 'USD' ? (whole === 1 ? 'dólar' : 'dólares') : (whole === 1 ? names[0] : names[1]);
      return (whole === 1 ? 'un' : spanishInteger(whole)) + ' ' + unit + ' con ' + spanishInteger(fraction);
    }
    const numeric = Number(raw.replace(/\./g, '').replace(',', '.'));
    return numeric === 1 ? 'un ' + names[0] : spanishNumber(raw) + ' ' + names[1];
