  text = text.replace(new RegExp('(' + moneyNumber + ')\\s+(USD|EUR|COP|MXN|ARS)\\b', 'gi'), (_, n, code) => money(code, n));
  text = text.replace(/\b(USD|EUR|COP|MXN|ARS)\b/gi, code => currencies[code.toUpperCase()][1]);
