const glossaryTerms = Object.entries(GLOSSARY).sort(([a], [b]) => b.length - a.length);
function applyGlossary(input) {
  let text = String(input);
  for (const [term, replacement] of glossaryTerms) {
    const escaped = term.replace(/[.*+?^$(){}|[\]\\]/g, '\\$&');
    const flags = /^[A-Z0-9]+$/.test(term) ? 'gu' : 'giu';
